function pt(x: number, y: number, pressure = 0.65): BezierPoint {
  return { x: Math.round(x * 10) / 10, y: Math.round(y * 10) / 10, pressure };
}

function makeRectPoints(x1: number, y1: number, x2: number, y2: number): BezierPoint[] {
  return [pt(x1, y1), pt(x2, y1), pt(x2, y2), pt(x1, y2), pt(x1, y1)];
}

function makeCirclePoints(cx: number, cy: number, r: number, steps = 32): BezierPoint[] {
  const pts: BezierPoint[] = [];
  for (let i = 0; i <= steps; i++) {
    const a = (i / steps) * Math.PI * 2;
    pts.push(pt(cx + Math.cos(a) * r, cy + Math.sin(a) * r));
  }
  return pts;
}

function makeStarPoints(cx: number, cy: number, outerR: number, innerR: number): BezierPoint[] {
  const pts: BezierPoint[] = [];
  for (let i = 0; i <= 10; i++) {
    const a = -Math.PI / 2 + (i * Math.PI) / 5;
    const r = i % 2 === 0 ? outerR : innerR;
    pts.push(pt(cx + Math.cos(a) * r, cy + Math.sin(a) * r));
  }
  return pts;
}

function makeLineStroke(
  id: string,
  x1: number,
  y1: number,
  x2: number,
  y2: number,
  color = '#1e3a8a',
  width = 2.2,
  dashed = false
): StrokeObject {
  return {
    id,
    layerId: 'layer-1',
    tool: 'pen',
    penType: 'ballpoint',
    color,
    width,
    opacity: 1,
    isShape: true,
    shapeType: 'line',
    lineStyle: dashed ? 'dashed' : 'solid',
    points: [pt(x1, y1), pt(x2, y2)],
  };
}

function makeRectStroke(
  id: string,
  x1: number,
  y1: number,
  x2: number,
  y2: number,
  color = '#1e3a8a',
  width = 2.2,
  fillColor?: string,
  dashed = false
): StrokeObject {
  return {
    id,
    layerId: 'layer-1',
    tool: 'pen',
    penType: 'ballpoint',
    color,
    width,
    opacity: 1,
    isShape: true,
    shapeType: 'rectangle',
    lineStyle: dashed ? 'dashed' : 'solid',
    fillColor,
    points: makeRectPoints(x1, y1, x2, y2),
  };
}

function makeCircleStroke(
  id: string,
  cx: number,
  cy: number,
  r: number,
  color = '#1e3a8a',
  width = 2.2,
  fillColor?: string
): StrokeObject {
  return {
    id,
    layerId: 'layer-1',
    tool: 'pen',
    penType: 'ballpoint',
    color,
    width,
    opacity: 1,
    isShape: true,
    shapeType: 'circle',
    fillColor,
    points: makeCirclePoints(cx, cy, r),
  };
}

function makeArrowStrokes(
  idPrefix: string,
  x1: number,
  y1: number,
  x2: number,
  y2: number,
  color = '#1e3a8a',
  width = 2.2,
  headLen = 10
): StrokeObject[] {
  const angle = Math.atan2(y2 - y1, x2 - x1);
  const a1 = angle + Math.PI - 0.48;
  const a2 = angle + Math.PI + 0.48;
  return [
    makeLineStroke(`${idPrefix}-shaft`, x1, y1, x2, y2, color, width),
    {
      id: `${idPrefix}-head`,
      layerId: 'layer-1',
      tool: 'pen',
      penType: 'ballpoint',
      color,
      width,
      opacity: 1,
      points: [
        pt(x2 + Math.cos(a1) * headLen, y2 + Math.sin(a1) * headLen),
        pt(x2, y2),
        pt(x2 + Math.cos(a2) * headLen, y2 + Math.sin(a2) * headLen),
      ],
    },
  ];
}

